#!/usr/bin/env bash
# Generated by Claude (Opus 5.5), 2026-10-25
# spsc-bench.sh - compare RingBuffer variants under real ITCH traffic replayed over UDP.
#
# Usage (from anywhere inside the repo):
#   spsc-bench.sh                       git:HEAD against the working-tree spsc.hpp
#   spsc-bench.sh VARIANT [VARIANT...]  each VARIANT is a header file defining RingBuffer<T, N>,
#                                       or git:<ref> for src/feed-handler/spsc.hpp at that commit
#
# For each variant it builds a spsc-bench binary (spsc-bench.cpp with -DSPSC_HEADER=...), then
# runs every variant once per round: start the receiver, wait until it has bound, replay the
# ITCH window with itch-replay, collect the JSON. Rounds rotate the order of the variants.
# A run is discarded (renamed .invalid) if the receiver lost packets or did not get exactly
# the messages, ticks and shares the sender sent. With two variants, bench-compare.py prints
# the change for each percentile; with any number, a table of medians follows.
#
# Environment:
#   ITCH_FILE     decompressed NASDAQ ITCH 5.0 file (default ~/itch-data/01302019.NASDAQ_ITCH50)
#   MODE          e2e or percall (default e2e; see spsc-bench.cpp)
#   SPEED         replay speed, times real time; 0 = as fast as possible (default 10)
#   FROM          start of the window, market time (default 09:30:00)
#   MESSAGES      ITCH messages in the window (default 20000000)
#   ROUNDS        runs per variant (default 5)
#   BUCKETS       RingBuffer size (default 65536, as in main.cpp)
#   SENDER_CORE, PRODUCER_CORE, CONSUMER_CORE   (default 1, 2, 3)
#   PORT          UDP port on 127.0.0.1 (default 12345)
#   CXX, CXXFLAGS compiler and flags (default: g++-14, -O2 -march=native -DNDEBUG)
#   NOISE         changes below this many percent are not reported (default 5)
#
# One-time setup on the Intel box:
#   Data:   mkdir -p ~/itch-data && cd ~/itch-data
#           wget 'https://emi.nasdaq.com/ITCH/Nasdaq%20ITCH/01302019.NASDAQ_ITCH50.gz'
#           gunzip 01302019.NASDAQ_ITCH50.gz
#   Socket: sudo sysctl -w net.core.rmem_max=134217728   (lets the receiver get its 64 MB buffer)
#   Cores:  sender, producer and consumer each need a quiet physical core. Boot with
#           isolcpus=1-3 nohz_full=1-3 rcu_nocbs=1-3, turn SMT off
#           (echo off | sudo tee /sys/devices/system/cpu/smt/control), and keep the fixed
#           2.4 GHz / Turbo off setup from docs/rolling-sum-division-removal.md.
set -euo pipefail

SRC="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(git -C "$SRC" rev-parse --show-toplevel)"
BUILD="$ROOT/build/spsc-bench-runs"
SPSC_REL="$(realpath --relative-to="$ROOT" "$SRC/../spsc.hpp")"

CXX="${CXX:-g++-14}"
CXXFLAGS="${CXXFLAGS:--O2 -march=native -DNDEBUG}"
ITCH_FILE="${ITCH_FILE:-$HOME/itch-data/01302019.NASDAQ_ITCH50}"
MODE="${MODE:-e2e}"
SPEED="${SPEED:-10}"
FROM="${FROM:-09:30:00}"
MESSAGES="${MESSAGES:-20000000}"
ROUNDS="${ROUNDS:-5}"
BUCKETS="${BUCKETS:-65536}"
SENDER_CORE="${SENDER_CORE:-1}"
PRODUCER_CORE="${PRODUCER_CORE:-2}"
CONSUMER_CORE="${CONSUMER_CORE:-3}"
PORT="${PORT:-12345}"

[ -f "$ITCH_FILE" ] || {
    echo "ITCH file not found: $ITCH_FILE (set ITCH_FILE; download steps are in the header of $0)" >&2
    exit 1
}

# CPU list ("1,5" or "2-3") to one number per line.
expand_cpus() {
    local part
    for part in ${1//,/ }; do
        if [[ $part == *-* ]]; then seq "${part%-*}" "${part#*-}"; else echo "$part"; fi
    done
}
siblings="$(cat "/sys/devices/system/cpu/cpu$PRODUCER_CORE/topology/thread_siblings_list" 2>/dev/null || true)"
if [ -n "$siblings" ] && expand_cpus "$siblings" | grep -qx "$CONSUMER_CORE"; then
    echo "warning: producer core $PRODUCER_CORE and consumer core $CONSUMER_CORE are hyperthreads of one" \
         "physical core; they share L1/L2, so the numbers will not match two separate cores" >&2
fi
rmem_max="$(cat /proc/sys/net/core/rmem_max 2>/dev/null || echo 0)"
if [ "$rmem_max" -lt $((64 << 20)) ]; then
    echo "warning: net.core.rmem_max is $rmem_max, the receiver asks for 64 MB; expect drops at high SPEED" \
         "(sudo sysctl -w net.core.rmem_max=134217728)" >&2
fi

mkdir -p "$BUILD"
rm -f "$BUILD"/*.json "$BUILD"/*.invalid "$BUILD"/*.log

[ $# -gt 0 ] || set -- git:HEAD "$SRC/../spsc.hpp"

# Resolve each variant to a header and a label.
headers=() labels=()
for v in "$@"; do
    i=${#headers[@]}
    if [[ $v == git:* ]]; then
        ref="${v#git:}"
        hdr="$BUILD/v$i-spsc.hpp"
        git -C "$ROOT" show "$ref:$SPSC_REL" >"$hdr"
        labels+=("spsc.hpp@$(git -C "$ROOT" rev-parse --short "$ref")")
    else
        hdr="$(realpath "$v")"
        [ -f "$hdr" ] || { echo "no such header: $v" >&2; exit 1; }
        if [ "$hdr" = "$(realpath "$SRC/../spsc.hpp")" ]; then labels+=("spsc.hpp (working tree)")
        elif [[ $hdr == "$ROOT"/* ]]; then labels+=("${hdr#"$ROOT"/}")
        else labels+=("$(basename "$hdr")"); fi
    fi
    headers+=("$hdr")
done

echo "Building ${#headers[@]} variant(s) and itch-replay..."
"$CXX" -std=c++23 -O2 -march=native "$SRC/itch-replay.cpp" -o "$BUILD/itch-replay"
for i in "${!headers[@]}"; do
    # shellcheck disable=SC2086
    "$CXX" -std=c++23 $CXXFLAGS -DSPSC_HEADER="\"${headers[$i]}\"" -DSPSC_BUCKETS="$BUCKETS" \
        "$SRC/spsc-bench.cpp" -lpthread -o "$BUILD/spsc-bench-v$i"
done

summary() { grep -m1 '^summary:' "$1" || echo "summary: none"; }

run_one() { # variant-index round
    local i=$1 round=$2
    local out="$BUILD/v$i-r$round.json" rlog="$BUILD/v$i-r$round-receiver.log" slog="$BUILD/v$i-r$round-sender.log"
    "$BUILD/spsc-bench-v$i" --mode "$MODE" --variant "${labels[$i]}" --out "$out" --port "$PORT" \
        --producer-core "$PRODUCER_CORE" --consumer-core "$CONSUMER_CORE" >"$rlog" 2>&1 &
    local pid=$! waited=0
    until grep -q '^ready' "$rlog"; do
        kill -0 "$pid" 2>/dev/null || { echo "receiver died:" >&2; cat "$rlog" >&2; exit 1; }
        sleep 0.05
    done
    taskset -c "$SENDER_CORE" "$BUILD/itch-replay" --file "$ITCH_FILE" --from "$FROM" \
        --messages "$MESSAGES" --speed "$SPEED" --port "$PORT" >"$slog" 2>&1
    # The sender ends the session; if every end-of-session packet was dropped, give up.
    while kill -0 "$pid" 2>/dev/null && [ $waited -lt 100 ]; do sleep 0.1; waited=$((waited + 1)); done
    kill "$pid" 2>/dev/null || true
    local status=0
    wait "$pid" || status=$?

    local sent got
    sent="$(summary "$slog")" got="$(summary "$rlog")"
    if [ "$status" -ne 0 ] || [ "$sent" != "$got" ]; then
        [ -f "$out" ] && mv "$out" "$out.invalid"
        echo "  ${labels[$i]}: INVALID (exit $status; sent ${sent#summary: }; received ${got#summary: })"
        grep -E '^(packets|INVALID)' "$rlog" | sed 's/^/    /' || true
    else
        echo "  ${labels[$i]}: $(grep -m1 '^sent in' "$slog")"
    fi
}

echo "Mode $MODE, $MESSAGES messages from $FROM at speed $SPEED, $ROUNDS round(s);" \
     "cores: sender $SENDER_CORE, producer $PRODUCER_CORE, consumer $CONSUMER_CORE"
n=${#headers[@]}
for round in $(seq "$ROUNDS"); do
    echo "Round $round of $ROUNDS..."
    for k in $(seq 0 $((n - 1))); do
        run_one $(((k + round - 1) % n)) "$round"
    done
done
echo

valid() { compgen -G "$BUILD/v$1-r*.json" >/dev/null; }
for i in "${!headers[@]}"; do
    valid "$i" || echo "no valid run for ${labels[$i]}" >&2
done

if [ "$n" -eq 2 ] && valid 0 && valid 1; then
    echo "Baseline: ${labels[0]}   New: ${labels[1]}"
    python3 "$SRC/bench-compare.py" --noise "${NOISE:-5}" \
        --baseline "$BUILD"/v0-r*.json --current "$BUILD"/v1-r*.json
    echo
fi

# Medians over the valid rounds, per variant and row.
python3 - "$BUILD" "$n" "${labels[@]}" <<'EOF'
import glob, json, statistics, sys
build, n, labels = sys.argv[1], int(sys.argv[2]), sys.argv[3:]
cols = ["p50", "p99", "p99.9", "p99.99", "max"]
print(f"{'median ns over runs':<40} {'runs':>4} " + " ".join(f"{c:>9}" for c in cols) + f" {'full':>6} {'Mtick/s':>8}")
for i in range(n):
    runs = [json.load(open(p)) for p in sorted(glob.glob(f"{build}/v{i}-r*.json"))]
    if not runs:
        continue
    full = statistics.median(r["context"]["full"] for r in runs)
    rate = statistics.median(r["context"]["mticks_per_s"] for r in runs)
    for b in runs[0]["benchmarks"]:
        vals = [statistics.median(next(x for x in r["benchmarks"] if x["name"] == b["name"])[c] for r in runs)
                for c in cols]
        name = f"{labels[i][:28]} {b['name'].split('/')[-1]}"
        print(f"{name:<40} {len(runs):>4} " + " ".join(f"{v:9.1f}" for v in vals) + f" {full:6.0f} {rate:8.2f}")
EOF
